SELECT *, AVG(amount) OVER w_running AS running_avg_amount, MAX(amount) OVER w_running AS running_max_amount, MIN(amount) OVER w_running AS running_min_amount, AVG(amount) OVER (PARTITION BY account_id ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS amount_avg_7d FROM transactions WHERE is_flagged = FALSE WINDOW w_running AS (PARTITION BY account_id, merchant ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
